INSERT INTO content_pages (content_key, page_kind, subject_id, topic_id, chapter_id, worksheet_id, title, source_format, source_path, content_json, content_hash) VALUES ('chapter:math:terme-gleichungen:terme-umformen', 'chapter', 'math', 'terme-gleichungen', 'terme-umformen', NULL, 'Terme umformen', 'md', 'content/base/math/terme-gleichungen/00-terme-umformen/overview.md', '{"title":"Terme umformen","content":[{"header":"Zusammenfassen","content":[{"markdown":"Terme mit gleichen Variablen und gleichen Exponenten können zusammengefasst werden."},{"type":"card","kind":"highlight","content":{"markdown":"$3x + 5x = 8x$\n\n$2a^2 - a^2 + 4a = a^2 + 4a$"}},{"type":"callout","content":{"markdown":"Nur gleichartige Terme dürfen zusammengefasst werden. $3x$ und $3x^2$ sind **nicht** gleichartig."}}]},{"header":"Ausmultiplizieren","content":[{"markdown":"Beim Ausmultiplizieren wenden wir das Distributivgesetz an."},{"type":"card","kind":"highlight","content":{"markdown":"$a dot (b + c) = a dot b + a dot c$"}},{"type":"card","kind":"concept","content":{"markdown":"$3 dot (x + 5) = 3x + 15$\n\n$-2 dot (x - 4) = -2x + 8$"}},{"type":"callout","content":{"markdown":"Achtung bei negativem Vorzeichen vor der Klammer: Das Minuszeichen ändert das Vorzeichen **jedes** Summanden."}}]},{"header":"Ausklammern","content":[{"markdown":"Ausklammern ist die Umkehrung des Ausmultiplizierens. Wir suchen den größten gemeinsamen Faktor aller Summanden."},{"type":"card","kind":"highlight","content":{"markdown":"$a dot b + a dot c = a dot (b + c)$"}},{"type":"card","kind":"concept","content":{"markdown":"$6x^2 + 4x = 2x dot (3x + 2)$\n\n$x^2 - x = x dot (x - 1)$"}}]},{"header":"Äquivalente Terme","content":[{"markdown":"Zwei Terme sind äquivalent, wenn sie für alle Variablenwerte denselben Wert liefern."},{"type":"card","kind":"concept","content":{"markdown":"$2(x + 3)$ und $2x + 6$ sind äquivalent.\n\nDas lässt sich durch Ausmultiplizieren zeigen: $2(x + 3) = 2x + 6$."}}]}]}'::jsonb, '559d52bc6d99fd827a7c0ff11cc88fe1ad75fad1827d7d1a158c3cfe85dadb50') ON CONFLICT (content_key) DO UPDATE SET page_kind = EXCLUDED.page_kind, subject_id = EXCLUDED.subject_id, topic_id = EXCLUDED.topic_id, chapter_id = EXCLUDED.chapter_id, worksheet_id = EXCLUDED.worksheet_id, title = EXCLUDED.title, source_format = EXCLUDED.source_format, source_path = EXCLUDED.source_path, content_json = EXCLUDED.content_json, content_hash = EXCLUDED.content_hash, updated_at = NOW();
INSERT INTO content_pages (content_key, page_kind, subject_id, topic_id, chapter_id, worksheet_id, title, source_format, source_path, content_json, content_hash) VALUES ('worksheet:math:terme-gleichungen:terme-umformen:terme-umformen', 'worksheet', 'math', 'terme-gleichungen', 'terme-umformen', 'terme-umformen', 'Terme umformen', 'md', 'content/base/math/terme-gleichungen/00-terme-umformen/worksheets/00-terme-umformen.md', '{"title":"Terme umformen","content":[{"header":"Checkpoint","content":[{"type":"group","macros":[{"type":"gap","content":{"markdown":"Fasse die gleichartigen Terme zusammen.\n\n$$\r\n5x^2 - 3x + 2x^2 + x = ￾0￾x^2 + ￾1￾x\r\n$$"},"gaps":[{"mode":"text","correct":["7","3","10"]},{"mode":"text","correct":["-2","2","4"]}]}]},{"type":"group","macros":[{"type":"inputTask","instruction":{"markdown":"Berechne den Wert von $f(a) = 3a^2 - 2a + 1$ für $a = 2$."},"answer":{"kind":"number","value":9},"why":{"markdown":"$f(2) = 3 dot 4 - 2 dot 2 + 1 = 12 - 4 + 1 = 9$"}}]},{"type":"group","macros":[{"type":"mcq","question":{"markdown":"Welches ist die vereinfachte Form von $-2(x - 3) + 4x$?"},"correct":[{"markdown":"$2x + 6$"}],"options":[{"markdown":"$2x + 6$"},{"markdown":"$2x - 6$"},{"markdown":"$-6x - 6$"},{"markdown":"$-2x - 6$"}],"single":true,"shuffleOptions":true,"wideLayout":true,"why":{"markdown":"Das Minuszeichen ändert das Vorzeichen **jedes** Summanden in der Klammer: $-2 dot (-3) = +6$. Also $-2x + 6 + 4x = 2x + 6$."}}]},{"type":"group","macros":[{"type":"mcq","question":{"markdown":"Welche der folgenden Ausdrücke sind äquivalent zu $6x^2 + 4x$?"},"correct":[{"markdown":"$2x(3x + 2)$"},{"markdown":"$2(3x^2 + 2x)$"}],"options":[{"markdown":"$2x(3x + 2)$"},{"markdown":"$2x(3x - 2)$"},{"markdown":"$2(3x^2 + 2x)$"},{"markdown":"$6x(x + 4)$"}],"single":false,"shuffleOptions":true,"wideLayout":true,"why":{"markdown":"Durch Ausmultiplizieren: $2x(3x+2) = 6x^2+4x$ ✓ und $2(3x^2+2x) = 6x^2+4x$ ✓. Bei $6x(x+4) = 6x^2+24x$ stimmt der zweite Summand nicht. Bei $2x(3x-2) = 6x^2-4x$ ist das Vorzeichen falsch."}}]}],"modifiers":["checkpoint"]},{"header":"Aufgaben","content":[{"type":"group","macros":[{"type":"handwrittenTask","instruction":{"markdown":"Vereinfache den folgenden Term vollständig. Zeige alle Zwischenschritte.\n\n$$\r\n3(2x - y) - 2(x - 3y) + y\r\n$$"},"hint":{"markdown":"Multipliziere jeden Term einzeln aus, bevor du zusammenfasst."},"answer":{"markdown":"$3(2x-y) - 2(x-3y) + y = 6x - 3y - 2x + 6y + y = 4x + 4y$"},"space":"m"}]},{"type":"group","macros":[{"type":"handwrittenTask","instruction":{"markdown":"Klammere den größten gemeinsamen Faktor vollständig aus:\n\n$$\r\n12x^3 - 8x^2 + 4x\r\n$$"},"hint":{"markdown":"Welcher Faktor steckt in allen drei Summanden?"},"answer":{"markdown":"$12x^3 - 8x^2 + 4x = 4x(3x^2 - 2x + 1)$"},"space":"m"}]}],"modifiers":["pdf","grid:squares"],"pdfAssetKey":"1ad6f578427da2130e6a8ddf136d5df749721463a97529e47e7f39899c54a29e.pdf"}]}'::jsonb, '79569f69efc1d8f008c099070f6c1e0c31926c61caecf2e25f4db65a7a68f8a2') ON CONFLICT (content_key) DO UPDATE SET page_kind = EXCLUDED.page_kind, subject_id = EXCLUDED.subject_id, topic_id = EXCLUDED.topic_id, chapter_id = EXCLUDED.chapter_id, worksheet_id = EXCLUDED.worksheet_id, title = EXCLUDED.title, source_format = EXCLUDED.source_format, source_path = EXCLUDED.source_path, content_json = EXCLUDED.content_json, content_hash = EXCLUDED.content_hash, updated_at = NOW();
INSERT INTO content_pages (content_key, page_kind, subject_id, topic_id, chapter_id, worksheet_id, title, source_format, source_path, content_json, content_hash) VALUES ('chapter:math:terme-gleichungen:binomische-formeln', 'chapter', 'math', 'terme-gleichungen', 'binomische-formeln', NULL, 'Binomische Formeln', 'md', 'content/base/math/terme-gleichungen/10-binomische-formeln/overview.md', '{"title":"Binomische Formeln","content":[{"header":"Die drei binomischen Formeln","content":[{"type":"card","kind":"highlight","content":{"markdown":"1. $(a + b)^2 = a^2 + 2 a b + b^2$\n\n2. $(a - b)^2 = a^2 - 2 a b + b^2$\n\n3. $(a + b)(a - b) = a^2 - b^2$"}}]},{"header":"Anwenden: Ausmultiplizieren","content":[{"markdown":"Wir erkennen das Muster und setzen die Terme für $a$ und $b$ ein."},{"type":"card","kind":"concept","content":{"markdown":"$(x + 3)^2 = x^2 + 2 dot x dot 3 + 9 = x^2 + 6x + 9$\n\n$(2x - 1)^2 = 4x^2 - 4x + 1$\n\n$(x + 5)(x - 5) = x^2 - 25$"}}]},{"header":"Anwenden: Faktorisieren","content":[{"markdown":"Erkennen wir eine binomische Struktur in einem Term, können wir rückwärts faktorisieren."},{"type":"card","kind":"concept","content":{"markdown":"$x^2 + 8x + 16 = (x + 4)^2$\n\n$9x^2 - 1 = (3x + 1)(3x - 1)$"}},{"type":"callout","content":{"markdown":"Bei der 1. und 2. Formel: Der mittlere Term ist immer $+- 2 a b$. Das hilft beim Erkennen."}}]},{"header":"Merkhilfe","content":[{"type":"table","headers":[{"markdown":"Formel"},{"markdown":"Erkennungsmerkmal"}],"rows":[[{"markdown":"$(a+b)^2$"},{"markdown":"Alle Vorzeichen positiv"}],[{"markdown":"$(a-b)^2$"},{"markdown":"Erster und letzter Term positiv, mittlerer negativ"}],[{"markdown":"$(a+b)(a-b)$"},{"markdown":"Zwei Quadrate mit Differenz, kein mittlerer Term"}]]}]}]}'::jsonb, 'faf681405c4b21562c78b523a76d9dec42c6da3cd089c7d5cfa9c41ca2d83397') ON CONFLICT (content_key) DO UPDATE SET page_kind = EXCLUDED.page_kind, subject_id = EXCLUDED.subject_id, topic_id = EXCLUDED.topic_id, chapter_id = EXCLUDED.chapter_id, worksheet_id = EXCLUDED.worksheet_id, title = EXCLUDED.title, source_format = EXCLUDED.source_format, source_path = EXCLUDED.source_path, content_json = EXCLUDED.content_json, content_hash = EXCLUDED.content_hash, updated_at = NOW();
INSERT INTO content_pages (content_key, page_kind, subject_id, topic_id, chapter_id, worksheet_id, title, source_format, source_path, content_json, content_hash) VALUES ('worksheet:math:terme-gleichungen:binomische-formeln:binomische-formeln', 'worksheet', 'math', 'terme-gleichungen', 'binomische-formeln', 'binomische-formeln', 'Binomische Formeln', 'md', 'content/base/math/terme-gleichungen/10-binomische-formeln/worksheets/00-binomische-formeln.md', '{"title":"Binomische Formeln","content":[{"header":"Checkpoint","content":[{"type":"group","macros":[{"type":"mcq","question":{"markdown":"Welche binomische Formel passt zu $(3x - 2)^2$?"},"correct":[{"markdown":"$(a - b)^2 = a^2 - 2 a b + b^2$"}],"options":[{"markdown":"$(a + b)^2 = a^2 + 2 a b + b^2$"},{"markdown":"$(a - b)^2 = a^2 - 2 a b + b^2$"},{"markdown":"$(a + b)(a - b) = a^2 - b^2$"}],"single":true,"shuffleOptions":true,"wideLayout":true,"why":{"markdown":"Der Ausdruck hat die Form $(a - b)^2$ mit $a = 3x$ und $b = 2$: Das Vorzeichen zwischen den Termen ist negativ, und es liegt ein Quadrat vor."}}]},{"type":"group","macros":[{"type":"inputTask","instruction":{"markdown":"Multipliziere $(x + 4)^2$ aus. Wie lautet der Koeffizient von $x$?"},"answer":{"kind":"number","value":8},"why":{"markdown":"$(x+4)^2 = x^2 + 2 dot x dot 4 + 16 = x^2 + 8x + 16$. Der mittlere Term ist immer $2 a b = 2 dot 1 dot 4 = 8$."}}]},{"type":"group","macros":[{"type":"inputTask","instruction":{"markdown":"Multipliziere $(2a - 3)^2$ aus. Wie lautet der konstante Term?"},"answer":{"kind":"number","value":9},"why":{"markdown":"$(2a-3)^2 = 4a^2 - 12a + 9$. Der konstante Term ist stets $b^2 = 3^2 = 9$."}}]},{"type":"group","macros":[{"type":"gap","content":{"markdown":"Ergänze das Ergebnis.\n\n$(x + 7)(x - 7) = x^2 - ￾0￾$"},"gaps":[{"mode":"text","correct":["49","14x","7"]}]}]}],"modifiers":["checkpoint"]},{"header":"Faktorisieren","content":[{"type":"group","macros":[{"type":"gap","content":{"markdown":"Faktorisiere $x^2 - 10x + 25$.\n\n$x^2 - 10x + 25 = (x - ￾0￾)^2$"},"gaps":[{"mode":"text","correct":["5","10","25"]}]}]},{"type":"group","macros":[{"type":"mcq","question":{"markdown":"Welche der folgenden Terme lassen sich als vollständiges Quadrat $(a +- b)^2$ schreiben?"},"correct":[{"markdown":"$x^2 + 6x + 9$"},{"markdown":"$4a^2 - 4a + 1$"}],"options":[{"markdown":"$4a^2 - 4a + 1$"},{"markdown":"$9x^2 + 4$"},{"markdown":"$x^2 + 6x + 9$"},{"markdown":"$x^2 + 6x + 4$"}],"single":false,"shuffleOptions":true,"wideLayout":true,"why":{"markdown":"$x^2+6x+9 = (x+3)^2$ ✓ (mittlerer Term $2 dot 1 dot 3 = 6$ ✓). $4a^2-4a+1 = (2a-1)^2$ ✓ (mittlerer Term $2 dot 2 dot 1 = 4$ ✓). Bei $x^2+6x+4$ wäre $b=3$ nötig, aber dann $b^2=9!=4$. $9x^2+4$ hat keinen mittleren Term und ist keine Differenz zweier Quadrate."}}]}]},{"header":"Aufgaben","content":[{"type":"group","macros":[{"type":"handwrittenTask","instruction":{"markdown":"Multipliziere aus und vereinfache vollständig. Zeige jeden Schritt.\n\n$$\r\n(2x + 3)^2 - (x - 1)^2\r\n$$"},"hint":{"markdown":"Wende auf beide Quadrate jeweils die passende binomische Formel an, bevor du subtrahierst."},"answer":{"markdown":"$(2x+3)^2 = 4x^2+12x+9$\n\n$(x-1)^2 = x^2-2x+1$\n\n$(2x+3)^2-(x-1)^2 = 4x^2+12x+9 - x^2+2x-1 = 3x^2+14x+8$"},"space":"l"}]},{"type":"group","macros":[{"type":"handwrittenTask","instruction":{"markdown":"Faktorisiere die folgenden Terme mithilfe der binomischen Formeln. Gib jeweils an, welche Formel du verwendest.\n\na) $9x^2 - 6x + 1$\n\nb) $4a^2 - 25$"},"hint":{"markdown":"Prüfe bei a): Ist der mittlere Term $-2 a b$? Bei b): Liegt eine Differenz zweier Quadrate vor?"},"answer":{"markdown":"a) $9x^2-6x+1 = (3x-1)^2$ (zweite Formel, $a=3x$, $b=1$)\n\nb) $4a^2-25 = (2a+5)(2a-5)$ (dritte Formel, $a=2a$, $b=5$)"},"space":"l"}]}],"modifiers":["pdf","grid:squares"],"pdfAssetKey":"7fa5313f1daf79653ac7a193ede2683a05dde5a209cb5dd72851436025276845.pdf"},{"header":"Challenges","content":[{"type":"group","macros":[{"type":"handwrittenTask","instruction":{"markdown":"Zeichne ein Quadrat mit Seitenlänge $(a + b)$ und unterteile es so, dass die Formel\n\n$$\r\n(a + b)^2 = a^2 + 2 a b + b^2\r\n$$\n\ngeometrisch sichtbar wird. Beschrifte alle Teilflächen."},"hint":{"markdown":"Markiere an den Seiten die Abschnitte $a$ und $b$ und ziehe von dort Hilfslinien ins Innere."},"answer":{"markdown":"Das Quadrat zerfällt in vier Teile: ein $a times a$-Quadrat, ein $b times b$-Quadrat und zwei Rechtecke der Fläche $a dot b$ — zusammen $a^2 + 2 a b + b^2$."},"space":"page"}]}],"modifiers":["challenge","pdf","grid:free"],"pdfAssetKey":"a3a4f51d98308d908d18022daa002b2ac1efa2d8f939a483b8de6c900fa2200c.pdf"}]}'::jsonb, 'e97031dce92d0d4c6bbb88daaeb8e504901a8f77d1cc458ba296b93572281dbd') ON CONFLICT (content_key) DO UPDATE SET page_kind = EXCLUDED.page_kind, subject_id = EXCLUDED.subject_id, topic_id = EXCLUDED.topic_id, chapter_id = EXCLUDED.chapter_id, worksheet_id = EXCLUDED.worksheet_id, title = EXCLUDED.title, source_format = EXCLUDED.source_format, source_path = EXCLUDED.source_path, content_json = EXCLUDED.content_json, content_hash = EXCLUDED.content_hash, updated_at = NOW();
INSERT INTO content_pages (content_key, page_kind, subject_id, topic_id, chapter_id, worksheet_id, title, source_format, source_path, content_json, content_hash) VALUES ('chapter:math:terme-gleichungen:bruchrechnung', 'chapter', 'math', 'terme-gleichungen', 'bruchrechnung', NULL, 'Bruchrechnung', 'md', 'content/base/math/terme-gleichungen/20-bruchrechnung/overview.md', '{"title":"Bruchrechnung","content":[{"header":"Kürzen und Erweitern","content":[{"markdown":"Beim **Kürzen** teilen wir Zähler und Nenner durch dieselbe Zahl, beim **Erweitern** multiplizieren wir beide mit derselben Zahl. Der Wert des Bruchs ändert sich dabei nicht, weil wir ihn im Grunde nur mit $1$ multiplizieren (z. B. $frac(4,4) = 1$)."},{"type":"card","kind":"highlight","content":{"markdown":"$frac(a dot k,b dot k) = frac(a,b)$ (Kürzen)\n\n$frac(a,b) = frac(a dot k,b dot k)$ (Erweitern)"}},{"type":"card","kind":"concept","content":{"markdown":"$frac(8,12) = frac(8 div 4,12 div 4) = frac(2,3)$ (Kürzen mit $k = 4$)\n\n$frac(2,3) = frac(2 dot 5,3 dot 5) = frac(10,15)$ (Erweitern mit $k = 5$)\n\n$frac(6x^2,4x) = frac(2x dot 3x,2x dot 2) = frac(3x,2)$ (gemeinsamer Faktor $2x$ gekürzt)"}},{"type":"card","kind":"warning","content":{"markdown":"Gekürzt werden darf nur, wenn Zähler **und** Nenner als Produkt mit demselben Faktor vorliegen. $frac(a+k,b+k) = frac(a,b)$ ist **falsch** — Summanden dürfen nicht gekürzt werden."}}]},{"header":"Addition und Subtraktion","content":[{"markdown":"Brüche können nur addiert und subtrahiert werden, wenn sie denselben Nenner haben."},{"type":"card","kind":"highlight","content":{"markdown":"$frac(a,c) + frac(b,c) = frac(a + b,c)$"}},{"type":"card","kind":"concept","content":{"markdown":"$frac(1,3) + frac(1,4) = frac(4,12) + frac(3,12) = frac(7,12)$\n\n$frac(x,x+1) - frac(2,x+1) = frac(x - 2,x+1)$"}}]},{"header":"Multiplikation","content":[{"markdown":"Bei der Multiplikation multiplizieren wir Zähler mit Zähler und Nenner mit Nenner."},{"type":"card","kind":"highlight","content":{"markdown":"$frac(a,b) dot frac(c,d) = frac(a dot c,b dot d)$"}},{"type":"card","kind":"concept","content":{"markdown":"$frac(2,3) dot frac(5,7) = frac(10,21)$"}}]},{"header":"Division: Mit Kehrbruch multiplizieren","content":[{"markdown":"Eine Division durch einen Bruch wird zu einer Multiplikation mit dem **Kehrbruch** (Zähler und Nenner des zweiten Bruchs vertauscht)."},{"type":"card","kind":"highlight","content":{"markdown":"$frac(a,b) : frac(c,d) = frac(a,b) dot frac(d,c) = frac(a dot d,b dot c)$"}},{"type":"card","kind":"concept","content":{"markdown":"$frac(x,2) : frac(x,4) = frac(x,2) dot frac(4,x) = 2$"}}]},{"header":"Bruchterme vereinfachen","content":[{"markdown":"Bei Bruchtermen kürzen wir gemeinsame Faktoren im Zähler und Nenner."},{"type":"card","kind":"concept","content":{"markdown":"$frac(x^2 - 4,x + 2) = frac((x+2)(x-2),x+2) = x - 2$"}},{"type":"callout","content":{"markdown":"Vor dem Kürzen unbedingt faktorisieren. Nur gemeinsame **Faktoren** dürfen gekürzt werden, keine Summanden."}}]},{"header":"Definitionsmenge","content":[{"markdown":"Ein Bruch ist nicht definiert, wenn der Nenner null ist."},{"type":"card","kind":"highlight","content":{"markdown":"Die Definitionsmenge schließt alle Werte aus, für die der Nenner 0 wird."}},{"type":"card","kind":"concept","content":{"markdown":"$frac(1,x-2)$ ist nicht definiert für $x = 2$."}}]}]}'::jsonb, '8820b1ad5b601431f43f91a5183a3aa414729dd0ebd1ec7ae0879130ac10f838') ON CONFLICT (content_key) DO UPDATE SET page_kind = EXCLUDED.page_kind, subject_id = EXCLUDED.subject_id, topic_id = EXCLUDED.topic_id, chapter_id = EXCLUDED.chapter_id, worksheet_id = EXCLUDED.worksheet_id, title = EXCLUDED.title, source_format = EXCLUDED.source_format, source_path = EXCLUDED.source_path, content_json = EXCLUDED.content_json, content_hash = EXCLUDED.content_hash, updated_at = NOW();
INSERT INTO content_pages (content_key, page_kind, subject_id, topic_id, chapter_id, worksheet_id, title, source_format, source_path, content_json, content_hash) VALUES ('worksheet:math:terme-gleichungen:bruchrechnung:bruchrechnung', 'worksheet', 'math', 'terme-gleichungen', 'bruchrechnung', 'bruchrechnung', 'Bruchrechnung', 'md', 'content/base/math/terme-gleichungen/20-bruchrechnung/worksheets/00-bruchrechnung.md', '{"title":"Bruchrechnung","content":[{"header":"Checkpoint","content":[{"type":"group","macros":[{"type":"inputTask","instruction":{"markdown":"Berechne $frac(3,8) + frac(1,4)$."},"answer":{"kind":"fraction","numerator":5,"denominator":8},"hint":{"markdown":"Erweitere $frac(1,4)$ auf den Nenner $8$."},"why":{"markdown":"$frac(3,8) + frac(1,4) = frac(3,8) + frac(2,8) = frac(5,8)$"}}]},{"type":"group","macros":[{"type":"inputTask","instruction":{"markdown":"Berechne $frac(5,6) dot frac(3,10)$."},"answer":{"kind":"fraction","numerator":1,"denominator":4},"why":{"markdown":"$frac(5,6) dot frac(3,10) = frac(15,60) = frac(1,4)$. Zähler mit Zähler, Nenner mit Nenner — dann kürzen."}}]},{"type":"group","macros":[{"type":"inputTask","instruction":{"markdown":"Kürze $frac(12,18)$ vollständig."},"answer":{"kind":"fraction","numerator":2,"denominator":3},"why":{"markdown":"Größter gemeinsamer Teiler von $12$ und $18$ ist $6$: $frac(12,18) = frac(12 div 6,18 div 6) = frac(2,3)$."}}]},{"type":"group","macros":[{"type":"mcq","question":{"markdown":"Welche der folgenden Vereinfachungen sind korrekt?"},"correct":[{"markdown":"$frac(2 a b,4a) = frac(b,2)$"},{"markdown":"$frac(6x^2,3x) = 2x$"}],"options":[{"markdown":"$frac(2 a b,4a) = frac(b,2)$"},{"markdown":"$frac(x + 2,x) = 2$"},{"markdown":"$frac(a + b,a) = b$"},{"markdown":"$frac(6x^2,3x) = 2x$"}],"single":false,"shuffleOptions":true,"wideLayout":true,"why":{"markdown":"Gekürzt werden darf nur, wenn Zähler **und** Nenner denselben Faktor als **Produkt** enthalten. $frac(a+b,a)$ und $frac(x+2,x)$ haben Summen im Zähler — Summanden dürfen nicht gekürzt werden."}}]}],"modifiers":["checkpoint"]},{"header":"Bruchterme vereinfachen","content":[{"type":"group","macros":[{"type":"gap","content":{"markdown":"Faktorisiere den Zähler mit der dritten binomischen Formel und kürze.\n\n$$\r\nfrac(x^2 - 9,x + 3) = ￾0￾\r\n$$"},"gaps":[{"mode":"text","correct":["x - 3","x + 3","x + 3 dot x - 3","x^2 - 9"]}]}]}]},{"header":"Aufgaben","content":[{"type":"group","macros":[{"type":"handwrittenTask","instruction":{"markdown":"Vereinfache den folgenden Bruchterm vollständig und gib die Definitionsmenge an.\n\n$$\r\nfrac(2x^2 - 8,x^2 - 4x + 4)\r\n$$"},"hint":{"markdown":"Faktorisiere Zähler und Nenner getrennt. Im Zähler hilft Ausklammern, im Nenner eine binomische Formel."},"answer":{"markdown":"Zähler: $2x^2-8 = 2(x^2-4) = 2(x+2)(x-2)$\n\nNenner: $x^2-4x+4 = (x-2)^2$\n\n$$\r\nfrac(2(x+2)(x-2),(x-2)^2) = frac(2(x+2),x-2)\r\n$$\n\nDefinitionsmenge: $RR without 2$"},"space":"l"}]},{"type":"group","macros":[{"type":"handwrittenTask","instruction":{"markdown":"Berechne und vereinfache so weit wie möglich. Gib die Definitionsmenge an.\n\n$$\r\nfrac(x + 1,x - 1) - frac(2,x - 1) + frac(1,x)\r\n$$"},"hint":{"markdown":"Die ersten beiden Brüche haben bereits denselben Nenner. Bringe erst die Summe auf einen gemeinsamen Nenner mit dem dritten."},"answer":{"markdown":"$frac(x+1-2,x-1) + frac(1,x) = frac(x-1,x-1) + frac(1,x) = 1 + frac(1,x) = frac(x+1,x)$\n\nDefinitionsmenge: $RR without {0, 1}$"},"space":"l"}]}],"modifiers":["pdf","grid:lines"],"pdfAssetKey":"27223425dcbe20bda15d4e1d124dcf88206661abb77493f951ce26c60880f86a.pdf"},{"header":"Challenges","content":[{"type":"group","macros":[{"type":"handwrittenTask","instruction":{"markdown":"Beweise, dass für alle $a, b != 0$ gilt:\n\n$$\r\nfrac((a + b)^2 - (a - b)^2,4 a b) = 1\r\n$$\n\nNutze dabei die binomischen Formeln."},"hint":{"markdown":"Multipliziere Zähler und Nenner zunächst einzeln aus — was fällt dir auf?"},"answer":{"markdown":"$(a+b)^2 = a^2+2 a b+b^2$\n\n$(a-b)^2 = a^2-2 a b+b^2$\n\n$(a+b)^2 - (a-b)^2 = (a^2+2 a b+b^2) - (a^2-2 a b+b^2) = 4 a b$\n\n$$\r\nfrac(4 a b,4 a b) = 1 quad quad \"für \" a, b != 0 checkmark\r\n$$"},"space":"l"}]}],"modifiers":["challenge","pdf"],"pdfAssetKey":"16b155cfc16ba2ea4d5e9af68ea321f4766b228cf0a1ff97d1c537453b99c151.pdf"}]}'::jsonb, 'b3982deba97cdb4b049c759a0e32ae5db361ef95f4bdcef13758c4551b1be2db') ON CONFLICT (content_key) DO UPDATE SET page_kind = EXCLUDED.page_kind, subject_id = EXCLUDED.subject_id, topic_id = EXCLUDED.topic_id, chapter_id = EXCLUDED.chapter_id, worksheet_id = EXCLUDED.worksheet_id, title = EXCLUDED.title, source_format = EXCLUDED.source_format, source_path = EXCLUDED.source_path, content_json = EXCLUDED.content_json, content_hash = EXCLUDED.content_hash, updated_at = NOW();
INSERT INTO content_pages (content_key, page_kind, subject_id, topic_id, chapter_id, worksheet_id, title, source_format, source_path, content_json, content_hash) VALUES ('chapter:math:vektorgeometrie:geraden', 'chapter', 'math', 'vektorgeometrie', 'geraden', NULL, 'Geraden im Raum', 'md', 'content/base/math/vektorgeometrie/200-geraden/overview.md', '{"title":"Geraden im Raum","content":[{"header":"Parameterform","content":[{"type":"card","kind":"highlight","content":{"markdown":"$g: arrow(x) = arrow(p) + t dot arrow(r), quad t in RR$\n\n- $arrow(p)$ ist der Ortsvektor eines Punkts auf der Geraden\n- $arrow(r)$ ist ein Richtungsvektor der Geraden\n- $t$ ist der Parameter"}},{"type":"image","source":"/content-assets/647cfb326cb3fbc904d18b74196449b4e50ec4fcb0b865d73318a406ed394c7d.svg","width":304,"height":333,"size":"L"},{"type":"card","kind":"concept","content":{"markdown":"$g: arrow(x) = vec(1,2,0) + t dot vec(1,0,1)$\n\n- Für $t = 0$ erhält man den Punkt $(1|2|0)$\n- Für $t = 1$ erhält man den Punkt $(2|2|1)$\n- Für $t = -1$ erhält man den Punkt $(0|2|-1)$"}}]},{"header":"Gerade mit zwei Punkten aufstellen","content":[{"markdown":"Aus zwei Punkten erhalten wir den Richtungsvektor mit dem Verbindungsvektor aus [Vektorarten](vektorarten)."},{"type":"card","kind":"highlight","content":{"markdown":"$g: arrow(x) = arrow(A) + t dot arrow(A B)$"}},{"type":"callout","content":{"markdown":"Bei einer Geraden ist nur die Richtung wichtig.\nDeshalb dürfen wir den Richtungsvektor vereinfachen.\n\n$vec(2,4,6)$ und $vec(1,2,3)$ beschreiben dieselbe Richtung."}}]},{"header":"Punktprobe","content":[{"markdown":"Um zu prüfen, ob ein Punkt $Q$ auf $g$ liegt, setzen wir seinen Ortsvektor in die Geradengleichung ein.\n\n1. $arrow(Q) = arrow(p) + t dot arrow(r)$ aufstellen\r\n2. $t$ berechnen\r\n3. Prüfen, ob derselbe Wert in allen drei Komponenten passt"},{"type":"card","kind":"concept","content":{"markdown":"$g: arrow(x) = vec(1,2,0) + t dot vec(1,0,1)$, $quad Q(3|2|2)$\n\nAus $x_1$ folgt $t = 2$.\n\nDann passen auch $x_2$ und $x_3$.\n\nAlso liegt $Q$ auf $g$."}}]},{"header":"Spurpunkte","content":[{"markdown":"Ein Spurpunkt ist der Schnittpunkt der Geraden mit einer [Koordinatenebene](koordinatensystem).\n\nFür den Spurpunkt in der $x_1 x_2$-Ebene setzen wir $x_3 = 0$ und berechnen danach den passenden Parameter."}]}]}'::jsonb, '941cd6001a37b013043acdeb54b0655c3391f409d94f7127b5ee67e33d38ef51') ON CONFLICT (content_key) DO UPDATE SET page_kind = EXCLUDED.page_kind, subject_id = EXCLUDED.subject_id, topic_id = EXCLUDED.topic_id, chapter_id = EXCLUDED.chapter_id, worksheet_id = EXCLUDED.worksheet_id, title = EXCLUDED.title, source_format = EXCLUDED.source_format, source_path = EXCLUDED.source_path, content_json = EXCLUDED.content_json, content_hash = EXCLUDED.content_hash, updated_at = NOW();
INSERT INTO content_pages (content_key, page_kind, subject_id, topic_id, chapter_id, worksheet_id, title, source_format, source_path, content_json, content_hash) VALUES ('worksheet:math:vektorgeometrie:geraden:geraden-im-raum', 'worksheet', 'math', 'vektorgeometrie', 'geraden', 'geraden-im-raum', 'Geraden im Raum', 'md', 'content/base/math/vektorgeometrie/200-geraden/worksheets/00-geraden.md', '{"title":"Geraden im Raum","content":[{"header":"Checkpoint","content":[{"type":"group","macros":[{"type":"mcq","question":{"markdown":"Welcher der folgenden Punkte liegt auf der Geraden\n\n$$\ng: arrow(x) = vec(1,2,0) + t dot vec(1,0,1)?\n$$"},"correct":[{"markdown":"$P(3 | 2 | 2)$"}],"options":[{"markdown":"$R(1 | 2 | 2)$"},{"markdown":"$Q(2 | 3 | 1)$"},{"markdown":"$P(3 | 2 | 2)$"}],"single":true,"shuffleOptions":true,"wideLayout":true,"why":{"markdown":"Für $t = 2$: $(1+2,\\; 2+0,\\; 0+2) = (3,2,2)$ — $P$ liegt auf $g$ ✓. Bei $Q$ liefert die zweite Komponente $2 + 0 dot t = 2 != 3$. Bei $R$ ergibt die erste Komponente $t=0$, aber dann ist $x_3 = 0 != 2$."}}]},{"type":"group","macros":[{"type":"inputTask","instruction":{"markdown":"Bestimme den Richtungsvektor der Geraden durch $A(2 | 1 | 3)$ und $B(5 | 3 | 1)$."},"answer":{"kind":"vector","values":[3,2,-2]},"hint":{"markdown":"Der Richtungsvektor ist der Verbindungsvektor $arrow(A B) = B - A$."},"why":{"markdown":"$arrow(A B) = vec(5-2,3-1,1-3) = vec(3,2,-2)$"}}]},{"type":"group","macros":[{"type":"inputTask","instruction":{"markdown":"Für welchen Wert von $t$ erreicht die Gerade\n\n$$\r\ng: arrow(x) = vec(2,1,0) + t dot vec(1,-1,2)\r\n$$\n\ndie dritte Koordinate $x_3 = 6$?"},"answer":{"kind":"number","value":3},"why":{"markdown":"$0 + 2t = 6 => t = 3$"}}]},{"type":"group","macros":[{"type":"mcq","question":{"markdown":"Welche der folgenden Geraden beschreiben dieselbe Gerade wie\n\n$$\ng: arrow(x) = vec(1,2,0) + t dot vec(2,0,2)?\n$$"},"correct":[{"markdown":"$h_1: arrow(x) = vec(3,2,2) + t dot vec(1,0,1)$"},{"markdown":"$h_2: arrow(x) = vec(1,2,0) + t dot vec(4,0,4)$"}],"options":[{"markdown":"$h_4: arrow(x) = vec(1,3,0) + t dot vec(2,0,2)$"},{"markdown":"$h_2: arrow(x) = vec(1,2,0) + t dot vec(4,0,4)$"},{"markdown":"$h_3: arrow(x) = vec(0,2,1) + t dot vec(2,0,2)$"},{"markdown":"$h_1: arrow(x) = vec(3,2,2) + t dot vec(1,0,1)$"}],"single":false,"shuffleOptions":true,"wideLayout":true,"why":{"markdown":"$h_1$: Stützpunkt $(3,2,2)$ liegt auf $g$ (bei $t=1$), Richtung ist $frac(1,2)arrow(r)$ ✓. $h_2$: Gleicher Stützpunkt, Richtung ist $2arrow(r)$ ✓. $h_3$: Liegt $(0,2,1)$ auf $g$? Aus $x_1$: $t=-frac(1,2)$, dann $x_3=0+2 dot (-frac(1,2))=-1!=1$ ✗. $h_4$: Zweite Komponente $3!=2$ und Richtung hat $x_2=0$ — liegt nicht auf $g$ ✗."}}]}],"modifiers":["checkpoint"]},{"header":"Spurpunkte","content":[{"type":"group","macros":[{"type":"gap","content":{"markdown":"Um den Spurpunkt einer Geraden in der $x_1x_2$-Ebene zu finden, setzt man\n\n$$\r\nx_3 = ￾0￾\r\n$$\n\nund berechnet dann den passenden Parameterwert."},"gaps":[{"mode":"text","correct":["0","1","t"]}]}]}]},{"header":"Aufgaben","content":[{"type":"group","macros":[{"type":"handwrittenTask","instruction":{"markdown":"a) Stelle die Parameterform der Geraden durch $A(2 | 1 | 3)$ und $B(5 | 3 | 1)$ auf.\n\nb) Überprüfe, ob der Punkt $P(11 | 7 |-3)$ auf der Geraden liegt."},"hint":{"markdown":"Für die Punktprobe: Setze den Ortsvektor von $P$ ein und prüfe, ob derselbe Wert $t$ in allen drei Komponenten passt."},"answer":{"markdown":"a) $arrow(A B) = vec(3,2,-2)$, also $g: arrow(x) = vec(2,1,3) + t dot vec(3,2,-2)$\n\nb) Aus $x_1$: $2+3t=11 => t=3$.\n\nProbe: $x_2 = 1+2 dot 3=7$ ✓, $x_3 = 3-2 dot 3=-3$ ✓ — $P$ liegt auf $g$."},"space":"l"}]},{"type":"group","macros":[{"type":"handwrittenTask","instruction":{"markdown":"Bestimme alle drei Spurpunkte der Geraden\n\n$$\r\ng: arrow(x) = vec(1,2,3) + t dot vec(2,-1,-1)\r\n$$"},"hint":{"markdown":"Setze für jeden Spurpunkt eine der drei Koordinaten gleich $0$ und löse nach $t$ auf."},"answer":{"markdown":"$x_1x_2$-Ebene ($x_3=0$): $3-t=0 => t=3$, Spurpunkt $S_(12)(7 | -1 | 0)$\n\n$x_1x_3$-Ebene ($x_2=0$): $2-t=0 => t=2$, Spurpunkt $S_(13)(5 | 0 | 1)$\n\n$x_2x_3$-Ebene ($x_1=0$): $1+2t=0 => t=-frac(1,2)$, Spurpunkt $S_(23)(0 | frac(5,2) | frac(7,2))$"},"space":"l"}]}],"modifiers":["pdf","grid:free"],"pdfAssetKey":"1f372d3f853b7c51e533a334c3c69149286616fad52fe0b209feb63283a6fa4f.pdf"},{"header":"Challenges","content":[{"type":"group","macros":[{"type":"handwrittenTask","instruction":{"markdown":"Gegeben sind die Gerade\n\n$$\r\ng: arrow(x) = vec(0,1,0) + t dot vec(1,0,1)\r\n$$\n\nund der Punkt $P(4 | 1 | 2)$.\n\nBestimme den Lotfußpunkt $F$ — also den Punkt auf $g$, der den kleinsten Abstand zu $P$ hat.\n\n> highlight\r\n> Der Lotfußpunkt erfüllt: $arrow(P F) perp arrow(r)$, d. h. $arrow(P F) dot arrow(r) = 0$."},"hint":{"markdown":"Schreibe $F$ in Abhängigkeit von $t$ und stelle die Bedingung $arrow(P F) dot arrow(r) = 0$ auf."},"answer":{"markdown":"$F = (t,\\; 1,\\; t)$, also $arrow(P F) = (t-4,\\; 0,\\; t-2)$.\n\nBedingung: $(t-4)dot 1 + 0 dot 0 + (t-2)dot 1 = 0 => 2t-6=0 => t=3$.\n\n$F = (3 | 1 | 3)$"},"space":"l"}]}],"modifiers":["challenge","pdf"],"pdfAssetKey":"c4b12831a1e590a2856b679778e4d69172e6da02b4ad01e5962c2a361a920c0a.pdf"}]}'::jsonb, 'dfa96b2612a97550cf7001955e4248c47f4c44e5d50144707fe95606c0a2e807') ON CONFLICT (content_key) DO UPDATE SET page_kind = EXCLUDED.page_kind, subject_id = EXCLUDED.subject_id, topic_id = EXCLUDED.topic_id, chapter_id = EXCLUDED.chapter_id, worksheet_id = EXCLUDED.worksheet_id, title = EXCLUDED.title, source_format = EXCLUDED.source_format, source_path = EXCLUDED.source_path, content_json = EXCLUDED.content_json, content_hash = EXCLUDED.content_hash, updated_at = NOW();
INSERT INTO content_pages (content_key, page_kind, subject_id, topic_id, chapter_id, worksheet_id, title, source_format, source_path, content_json, content_hash) VALUES ('chapter:math:vektorgeometrie:lineare-abhaengigkeit', 'chapter', 'math', 'vektorgeometrie', 'lineare-abhaengigkeit', NULL, 'Lineare Abhängigkeit', 'md', 'content/base/math/vektorgeometrie/210-lineare-abhaengigkeit/overview.md', '{"title":"Lineare Abhängigkeit","content":[{"header":"Bedeutung","content":[{"markdown":"Zwei Vektoren sind linear abhängig, wenn einer ein Vielfaches des anderen ist."},{"type":"card","kind":"highlight","content":{"markdown":"$arrow(b) = s dot arrow(a)$ für ein $s in RR$"}},{"markdown":"Dann zeigen beide Vektoren in dieselbe oder in die entgegengesetzte Richtung. Sie sind also parallel."}]},{"header":"Prüfung","content":[{"markdown":"Wir vergleichen die Faktoren in allen Komponenten."},{"type":"formula","content":{"markdown":"$$\ns dot a_1 &= b_1 \\\r\n  s dot a_2 &= b_2 \\\r\n  s dot a_3 &= b_3\n$$"}},{"type":"card","kind":"highlight","content":{"markdown":"Ist der Faktor überall gleich, dann sind die Vektoren linear abhängig.\n\nIst der Faktor nicht überall gleich, dann sind sie linear unabhängig."}},{"type":"card","kind":"concept","content":{"markdown":"$arrow(a) = vec(1,2,3)$, $arrow(b) = vec(2,4,6)$\n\nIn allen drei Komponenten ist der Faktor $2$.\n\nAlso sind die Vektoren linear abhängig."}},{"type":"card","kind":"concept","content":{"markdown":"$arrow(a) = vec(1,2,3)$, $arrow(b) = vec(2,4,7)$\n\nDer Faktor passt nicht in allen Komponenten.\n\nAlso sind die Vektoren linear unabhängig."}}]}]}'::jsonb, '6c7ac7252debed9df6c3c9aafdeff29398e4c40f3dcc081b1dd4ffb2b60cab23') ON CONFLICT (content_key) DO UPDATE SET page_kind = EXCLUDED.page_kind, subject_id = EXCLUDED.subject_id, topic_id = EXCLUDED.topic_id, chapter_id = EXCLUDED.chapter_id, worksheet_id = EXCLUDED.worksheet_id, title = EXCLUDED.title, source_format = EXCLUDED.source_format, source_path = EXCLUDED.source_path, content_json = EXCLUDED.content_json, content_hash = EXCLUDED.content_hash, updated_at = NOW();
INSERT INTO content_pages (content_key, page_kind, subject_id, topic_id, chapter_id, worksheet_id, title, source_format, source_path, content_json, content_hash) VALUES ('chapter:math:vektorgeometrie:lage-geraden', 'chapter', 'math', 'vektorgeometrie', 'lage-geraden', NULL, 'Lagebeziehungen von Geraden', 'md', 'content/base/math/vektorgeometrie/220-lage-geraden/overview.md', '{"title":"Lagebeziehungen von Geraden","content":[{"header":"Lage bestimmen","content":[{"type":"image","source":"/content-assets/8edfb0ae0a99448306d216aed9cc11238ed3b53466c95c77e381592b6b04bce2.svg","width":818,"height":517,"size":"L"},{"markdown":"Wir überprüfen, ob die beiden Richtungsvektoren linear abhängig sind."},{"type":"card","kind":"highlight","content":{"markdown":"- Linear abhängig -> die Geraden sind **parallel** oder **identisch**\n\n- Linear unabhängig -> die Geraden sind **schneidend** oder **windschief**"}},{"type":"subheader","header":{"markdown":"Parallel oder identisch"}},{"markdown":"Sind die Richtungsvektoren linear abhängig, prüfen wir einen Punkt von $h$ auf $g$.\n\n1. Den Punkt mit Ortsvektor $arrow(q)$ in $g$ einsetzen\r\n2. Hat die Punktprobe eine Lösung, sind die Geraden identisch\r\n3. Sonst sind sie parallel"},{"type":"subheader","header":{"markdown":"Schneidend oder windschief"}},{"markdown":"Sind die Richtungsvektoren linear unabhängig, setzen wir beide Geradengleichungen gleich."},{"type":"card","kind":"highlight","content":{"markdown":"$arrow(p) + t dot arrow(u) = arrow(q) + s dot arrow(v)$"}},{"markdown":"Zum Lösen bringen wir das LGS mit dem [Gauss-Verfahren](../gleichungssysteme/gauss-verfahren) in Treppenform.\n\n- Hat das LGS eine Lösung, dann schneiden sich die Geraden.\r\n- Hat das LGS keine Lösung, dann sind sie windschief."}]},{"header":"Schnittpunkt berechnen","content":[{"markdown":"1. LGS lösen\r\n2. Den gefundenen Parameter in eine Geradengleichung einsetzen\r\n3. Den Punkt als Schnittpunkt angeben"},{"type":"card","kind":"concept","content":{"markdown":"$g: arrow(x) = vec(0,0,1) + t dot vec(1,1,0)$\n\n$h: arrow(x) = vec(2,0,1) + s dot vec(0,1,0)$\n\nAus dem Gleichsetzen folgt $t = 2$ und $s = 2$.\n\nDer Schnittpunkt ist $S(2|2|1)$."}}]}]}'::jsonb, '92494ad6a0015f6ed3d853feaa7e19088367cd70805dabd1667c48c15f0fdffe') ON CONFLICT (content_key) DO UPDATE SET page_kind = EXCLUDED.page_kind, subject_id = EXCLUDED.subject_id, topic_id = EXCLUDED.topic_id, chapter_id = EXCLUDED.chapter_id, worksheet_id = EXCLUDED.worksheet_id, title = EXCLUDED.title, source_format = EXCLUDED.source_format, source_path = EXCLUDED.source_path, content_json = EXCLUDED.content_json, content_hash = EXCLUDED.content_hash, updated_at = NOW();
INSERT INTO content_pages (content_key, page_kind, subject_id, topic_id, chapter_id, worksheet_id, title, source_format, source_path, content_json, content_hash) VALUES ('worksheet:math:vektorgeometrie:lage-geraden:lagebeziehungen-von-geraden', 'worksheet', 'math', 'vektorgeometrie', 'lage-geraden', 'lagebeziehungen-von-geraden', 'Lagebeziehungen von Geraden', 'md', 'content/base/math/vektorgeometrie/220-lage-geraden/worksheets/00-lage-geraden.md', '{"title":"Lagebeziehungen von Geraden","content":[{"header":"Checkpoint","content":[{"type":"group","macros":[{"type":"mcq","question":{"markdown":"Bestimme die Lage der Geraden\n\n$$\ng: arrow(x) = vec(1,2,0) + t dot vec(2,-1,3), quad quad h: arrow(x) = vec(0,1,1) + s dot vec(4,-2,6)\n$$"},"correct":[{"markdown":"parallel"}],"options":[{"markdown":"parallel"},{"markdown":"identisch"},{"markdown":"schneidend"},{"markdown":"windschief"}],"single":true,"shuffleOptions":true,"wideLayout":true,"why":{"markdown":"$vec(4,-2,6) = 2vec(2,-1,3)$ — die Richtungsvektoren sind linear abhängig. Punktprobe: Liegt $(0,1,1)$ auf $g$? Aus $x_1$: $t=-frac(1,2)$, dann $x_2 = 2-(-frac(1,2))=frac(5,2)!=1$ — nicht auf $g$. Also parallel."}}]},{"type":"group","macros":[{"type":"mcq","question":{"markdown":"Bestimme die Lage der Geraden\n\n$$\ng: arrow(x) = vec(0,0,0) + t dot vec(1,2,1), quad quad h: arrow(x) = vec(2,4,2) + s dot vec(-1,-2,-1)\n$$"},"correct":[{"markdown":"identisch"}],"options":[{"markdown":"identisch"},{"markdown":"windschief"},{"markdown":"schneidend"},{"markdown":"parallel"}],"single":true,"shuffleOptions":true,"wideLayout":true,"why":{"markdown":"$vec(-1,-2,-1) = -1 dot vec(1,2,1)$ — linear abhängig. Punktprobe: Liegt $(2,4,2)$ auf $g$? Für $t=2$: $(2,4,2)$ ✓ — also identisch."}}]},{"type":"group","macros":[{"type":"inputTask","instruction":{"markdown":"Berechne den Schnittpunkt der Geraden\n\n$$\r\ng: arrow(x) = vec(0,0,0) + t dot vec(1,1,0), quad quad h: arrow(x) = vec(2,0,0) + s dot vec(0,1,0)\r\n$$"},"answer":{"kind":"vector","values":[2,2,0]},"hint":{"markdown":"Setze die Geradengleichungen gleich und löse das entstehende Gleichungssystem."},"why":{"markdown":"Gleichsetzen: $t = 2$ (aus $x_1$), $s = 2$ (aus $x_2$), $x_3 = 0$ ✓. Schnittpunkt: $S(2 | 2 | 0)$."}}]},{"type":"group","macros":[{"type":"mcq","question":{"markdown":"Welche Aussagen über windschiefe Geraden sind richtig?"},"correct":[{"markdown":"Windschiefe Geraden haben keinen gemeinsamen Punkt."},{"markdown":"Windschiefe Geraden sind nicht parallel."},{"markdown":"Windschiefe Geraden können nur im dreidimensionalen Raum auftreten."}],"options":[{"markdown":"Windschiefe Geraden stehen senkrecht aufeinander."},{"markdown":"Windschiefe Geraden können nur im dreidimensionalen Raum auftreten."},{"markdown":"Windschiefe Geraden sind nicht parallel."},{"markdown":"Windschiefe Geraden haben keinen gemeinsamen Punkt."}],"single":false,"shuffleOptions":true,"wideLayout":true,"why":{"markdown":"Windschief bedeutet: linear unabhängige Richtungsvektoren, aber kein Schnittpunkt. Senkrecht stehen sie nur, wenn zusätzlich $arrow(u) dot arrow(v) = 0$ gilt — das ist kein allgemeines Merkmal. In der Ebene ($RR^2$) schneiden sich zwei nicht-parallele Geraden immer."}}]}],"modifiers":["checkpoint"]},{"header":"Fallunterscheidung","content":[{"type":"group","macros":[{"type":"gap","content":{"markdown":"Wenn die Richtungsvektoren linear abhängig sind und der Stützpunkt von $h$ **nicht** auf $g$ liegt, dann sind die Geraden\n\n￾0￾."},"gaps":[{"mode":"text","correct":["parallel","identisch","windschief"]}]}]}]},{"header":"Aufgaben","content":[{"type":"group","macros":[{"type":"handwrittenTask","instruction":{"markdown":"Untersuche die Lage der Geraden\n\n$$\r\ng: arrow(x) = vec(1,0,2) + t dot vec(1,1,-1), quad quad h: arrow(x) = vec(3,2,0) + s dot vec(2,2,-2)\r\n$$\n\nGehe nach dem Entscheidungsbaum vor: Prüfe zunächst die Richtungsvektoren, führe dann ggf. eine Punktprobe oder ein LGS durch und begründe dein Ergebnis."},"hint":{"markdown":"Vergleiche die Richtungsvektoren komponentenweise. Sind sie proportional?"},"answer":{"markdown":"$vec(2,2,-2) = 2vec(1,1,-1)$ — linear abhängig.\n\nPunktprobe: Liegt $(3,2,0)$ auf $g$? Aus $x_1$: $1+t=3 => t=2$. Dann $x_2=0+2=2$ ✓, $x_3=2-2=0$ ✓.\n\n**Die Geraden sind identisch.**"},"space":"page"}]},{"type":"group","macros":[{"type":"handwrittenTask","instruction":{"markdown":"Untersuche die Lage der Geraden\n\n$$\r\ng: arrow(x) = vec(1,0,2) + t dot vec(1,2,0), quad quad h: arrow(x) = vec(0,1,1) + s dot vec(1,0,1)\r\n$$\n\nFalls die Geraden einen Schnittpunkt haben, berechne ihn."},"hint":{"markdown":"Prüfe zuerst die Richtungsvektoren. Falls sie linear unabhängig sind, stelle das LGS auf und löse es mit dem Gauss-Verfahren."},"answer":{"markdown":"Richtungsvektoren $(1,2,0)$ und $(1,0,1)$: nicht proportional — linear unabhängig.\n\nLGS aus Gleichsetzen:\n\n$1+t = s$ (I), $2t = 1$ (II), $2 = 1+s$ (III)\n\nAus (II): $t=frac(1,2)$. Aus (III): $s=1$. In (I): $1+frac(1,2)=frac(3,2)!=1$ — **Widerspruch**.\n\n**Die Geraden sind windschief.**"},"space":"l"}]}],"modifiers":["pdf","grid:squares"],"pdfAssetKey":"54aab3d7b3690844be5251c419231330f5386c1b170c916140fa81bc39f5fc49.pdf"},{"header":"Challenges","content":[{"type":"group","macros":[{"type":"handwrittenTask","instruction":{"markdown":"Gegeben sind drei Geraden:\n\n$$\r\ng: arrow(x) = vec(0,0,0) + t dot vec(1,0,0)\r\n$$\n\n$$\r\nh: arrow(x) = vec(1,1,0) + s dot vec(0,-1,0)\r\n$$\n\n$$\r\nk: arrow(x) = vec(0,0,1) + r dot vec(1,0,0)\r\n$$\n\nBestimme alle drei paarweisen Lagebeziehungen ($g$ und $h$, $g$ und $k$, $h$ und $k$) vollständig. Jedes der vier möglichen Ergebnisse (identisch, parallel, schneidend, windschief) tritt dabei mindestens einmal auf — welche drei?"},"hint":{"markdown":"Beginne jeweils mit dem Vergleich der Richtungsvektoren."},"answer":{"markdown":"**$g$ und $h$:** Richtungsvektoren $(1,0,0)$ und $(0,-1,0)$ — linear unabhängig. LGS: $t=1$ (aus $x_1$), $s=1$ (aus $x_2$), $0=0$ (aus $x_3$) ✓ — **schneidend**, $S(1|0|0)$.\n\n**$g$ und $k$:** Richtungsvektoren $(1,0,0)$ und $(1,0,0)$ — linear abhängig. Liegt $(0,0,1)$ auf $g$? Aus $x_3$: $0!=1$ — **parallel**.\n\n**$h$ und $k$:** Richtungsvektoren $(0,-1,0)$ und $(1,0,0)$ — linear unabhängig. LGS: $1=r$ (aus $x_1$), $1-s=0$ (aus $x_2$), $0=1$ (aus $x_3$) — **Widerspruch**, **windschief**."},"space":"page"}]}],"modifiers":["challenge","pdf"],"pdfAssetKey":"23c09639a410be43219e97b406c9c643a6ded1c491e95075d11144ff0f4c5665.pdf"}]}'::jsonb, 'bf21b3123f2de8a3d847ffa26e38276cf156120eb02fe502e12c553eda3118c7') ON CONFLICT (content_key) DO UPDATE SET page_kind = EXCLUDED.page_kind, subject_id = EXCLUDED.subject_id, topic_id = EXCLUDED.topic_id, chapter_id = EXCLUDED.chapter_id, worksheet_id = EXCLUDED.worksheet_id, title = EXCLUDED.title, source_format = EXCLUDED.source_format, source_path = EXCLUDED.source_path, content_json = EXCLUDED.content_json, content_hash = EXCLUDED.content_hash, updated_at = NOW();
